<template>
  <CanvassingProjectDashboard
    v-if="projectShortInfo?.type === 'canvassing'"
    tab="responses"
    :project-id="projectId"
    :project-start-end-date="{ start: projectShortInfo.start_date, end: projectShortInfo.end_date }"
  />
</template>

<script setup lang="ts">
import type { ProjectShortInfo } from '~/client';

definePageMeta({
  roles: ['manager', 'admin'],
  backLabel: 'dashboard',
  backGroup: 'project-dashboard',
});

interface Props {
  projectShortInfo?: ProjectShortInfo;
}

const props = defineProps<Props>();
const route = useRoute('projects-id-dashboard-responses');
const projectId = computed(() => route.params.id);

// Tabs exist only on the canvassing dashboard — a signature project has just /dashboard.
watch(
  () => props.projectShortInfo?.type,
  (type) => {
    if (type && type !== 'canvassing') {
      navigateTo({ name: 'projects-id-dashboard', params: { id: projectId.value } }, { replace: true });
    }
  },
  { immediate: true }
);

useHead({
  title: computed(() => props.projectShortInfo?.name ?? ''),
});
</script>
